using MegaCrit.Sts2.Core.Combat;
using MegaCrit.Sts2.Core.Entities.Cards;
using MegaCrit.Sts2.Core.GameActions.Multiplayer;
using MegaCrit.Sts2.Core.HoverTips;
using MegaCrit.Sts2.Core.Localization.DynamicVars;
using MegaCrit.Sts2.Core.Models;

namespace Downfall.Collector.Cards;

/// <summary>
/// Bellow (CollectorBellow, Token generated by Billow, 1 -> 0 cost, Skill, Ethereal, Exhaust):
/// Apply Doom equal to the Block lost at the start of this turn.
/// </summary>
public sealed class CollectorBellow() : CollectorTokenCard(1, CardType.Skill, CardRarity.Token, TargetType.AnyEnemy)
{
    public override IEnumerable<CardKeyword> CanonicalKeywords =>
        [CardKeyword.Ethereal, CardKeyword.Exhaust];

    protected override IEnumerable<DynamicVar> CanonicalVars =>
    [
        new CalculationBaseVar(0m),
        new CalculationExtraVar(1m),
        new CalculatedVar("DoomAmount").WithMultiplier((card, _) =>
        {
            if (card.CombatState is null || card.Owner is null)
                return 0m;
            return CollectorCombatState.Get(card.CombatState).GetPlayer(card.Owner).LastTurnUnusedBlock;
        })
    ];

    protected override IEnumerable<IHoverTip> ExtraHoverTips =>
    [
        DoomHoverTip
    ];

    protected override async Task OnCollectorPlay(PlayerChoiceContext choiceContext, CardPlay cardPlay, CardModel? pyredCard)
    {
        if (CombatState is null || !Owner.Creature.IsAlive || CombatManager.Instance.IsOverOrEnding)
            return;

        var target = ResolveTarget(Owner, cardPlay.Target);
        if (target is null)
            return;

        int doom = CollectorCombatState.Get(CombatState).GetPlayer(Owner).LastTurnUnusedBlock;
        if (doom > 0)
        {
            await CollectorMechanics.ApplyDoomAsync(choiceContext, target, doom, Owner.Creature, this);
        }
    }

    protected override void OnUpgrade()
    {
        EnergyCost.UpgradeBy(-1);
    }
}
